// wdbc-1rno: ручная кнопка (частота «раз в 12-Cor.b ч» и добровольный возврат не автоматизированы).
const corBonus = Number(actor.system.corruptionBonus) || 0;
const norm = s => String(s || "").toLowerCase().replace(/\s+/g, " ").trim();
const already = actor.items.some(i => i.type === "trait" && norm(i.name.split("/")[0]) === "incorporeal");
if (already) {
  ui.notifications?.warn("Пространственная Нестабильность: Incorporeal уже есть на акторе — сначала уберите вручную.");
} else {
  const pack = game.packs.get("warhammer-dbc.traits");
  const lib = pack ? await pack.getDocuments() : [];
  const src = lib.find(d => norm(d.name.split("/")[0]) === "incorporeal");
  if (src) {
    const d = src.toObject(); delete d._id;
    await actor.createEmbeddedDocuments("Item", [d]);
  }
  await ChatMessage.create({ speaker,
    content: `<b>Пространственная Нестабильность:</b> Трейт Incorporeal выдан на ${corBonus} Раундов (или до добровольного возврата свободным действием) — уберите Черту вручную по истечении времени.` });
}
